"""FAQ / help of Easy2edit in three layers: user (a logged-in member), admin (not a super admin) and super admin. The Dutch source texts; every other language is made from these
(manage.py faq_translate -> data/faq.json). Items only show when their module or plugin is on and the person has the rights.
need: "all", "member" (logged in), "staff" (super admin), "<module>:<level>" (module on and this level or more; level 0 = every logged-in person),
"plugin:<name>" (plugin on, super admins) or "plugin+:<name>" (plugin on, every logged-in person).
art: the picture of a group (drawn in the colours of the active theme in the front end)."""

GROUPS = [
    ("start", "user", "Aan de slag", "start"),
    ("account", "user", "Mijn account", "security"),
    ("social", "user", "Community en games", "community"),
    ("money", "user", "Abonnementen, donaties en bestellingen", "shop"),
    ("site", "admin", "Pagina's en menu", "pages"),
    ("edit", "admin", "Bewerken op de website", "edit"),
    ("design", "admin", "Vormgeving en media", "design"),
    ("shop", "admin", "Webshop, abonnementen en donaties", "shop"),
    ("community", "admin", "Community beheren", "community"),
    ("adminplug", "admin", "Plugins en spelletjes beheren", "system"),
    ("people", "admin", "Gebruikers en rechten", "people"),
    ("security", "admin", "Beveiliging", "security"),
    ("system", "super", "Systeem en plugins", "system"),
]

ITEMS = [
    ("what", "user", "start", "all", "Wat is Easy2edit?", "Easy2edit is een eenvoudig, modulair beheersysteem voor websites en portals. Je zet alleen aan wat je nodig hebt: pagina's, webshop, community, abonnementen, donaties en meer. Wat uit staat, komt nergens in beeld."),
    ("dash", "user", "start", "member", "Wat vind ik in mijn dashboard?", "Het dashboard is je persoonlijke omgeving. Links kies je tussen Menu en Tegels: in Tegels zie je per onderdeel een groot tegeltje, in Menu een lijst. Boven in de zoekbalk zoek je in alle instellingen, en met het sterretje maak je een snelkoppeling op je dashboard."),
    ("search", "user", "start", "member", "Hoe zoek ik een instelling?", "Typ in de zoekbalk bovenin het dashboard een woord, in elke taal. Je ziet alleen resultaten waar je toegang toe hebt. Klik je op een resultaat, dan opent het goede scherm en wordt het juiste blok of tabblad geopend."),
    ("lang", "user", "start", "all", "Hoe wissel ik van taal?", "Kies bovenin de taalkeuze. Alle teksten staan in alle talen klaar; alleen de talen die aan staan zie je in de keuze. De taal wordt onthouden voor je volgende bezoek."),
    ("mode", "user", "start", "all", "Licht of donker?", "Met de zon- of maanknop bovenin wissel je tussen een lichte en een donkere weergave. De kleuren van de website blijven die van het thema."),
    ("pages", "admin", "site", "pages:1", "Hoe beheer ik pagina's?", "Ga naar Admin → Pagina's. Daar staan alle pagina's van de website, de eigen pagina's en de links. Per pagina zet je de pagina aan of uit, kies je wie hem ziet (iedereen, ingelogde gebruikers of alleen bezoekers) en stel je naam, adres en SEO per taal in."),
    ("newitem", "admin", "site", "pages:3", "Hoe maak ik een nieuw item?", "In het tabblad Menu klik je op + Nieuw item. Kies een eigen pagina met tekst, een link naar een adres of een menu-item dat alleen tekst is en een dropdown opent. Is Claude gekoppeld, dan typ je de naam één keer en maakt Claude hem in alle talen."),
    ("menu", "admin", "site", "pages:2", "Hoe maak ik een dropdown-menu?", "Sleep in Pagina's → Menu een pagina met het sleepicoon op een ander menu-item, dan wordt het een submenu. Sleep je op de rand van een item, dan zet je het ervoor of erna. Sleep een item terug naar 'Niet in het menu' om het uit het menu te halen."),
    ("menuset", "admin", "site", "pages:3", "Hoe stel ik de vorm van het menu in?", "Kies in Pagina's → Menu → Instellingen per apparaat (computer, tablet, telefoon) de vorm: menubalk, hamburger, zijpaneel, volledig scherm of een balk onderaan. Ook stel je het submenu, de stijl, de grootte en de positie van menu en hamburger-icoon in. Het voorbeeld laat meteen zien hoe het wordt."),
    ("header", "admin", "site", "pages:3", "Hoe pas ik de header aan?", "In de menu-instellingen kies je de hoogte, de achtergrondkleur, de doorzichtigheid en de vervaging van de header. Ook bepaal je wat er na het scrollen gebeurt: niets, een schaduw, een zwevende balk of de header verdwijnt bij naar beneden scrollen."),
    ("slug", "admin", "site", "pages:2", "Kan een pagina per taal een eigen adres hebben?", "Ja. Open de instellingen van een pagina en kies het tabblad Adres. Daar staat het adres in elke taal. Een bezoeker komt met elk adres op dezelfde pagina. Talen die uit staan krijgen vanzelf ook een adres, zodat het klaarstaat."),
    ("private", "admin", "site", "pages:2", "Wat zijn privé pagina's?", "Privé pagina's zijn alleen voor ingelogde leden en staan op /dashboard/<pagina>. Ze krijgen een eigen menu in de header van het dashboard. Maak ze in Admin → Pagina's op het tabblad Privé."),
    ("editmode", "admin", "edit", "edit_mode:1", "Hoe bewerk ik een pagina op de website?", "Zet de schakelaar Bewerken aan in de header. Teksten met een stippellijn klik je aan om ze te wijzigen. Afbeeldingen krijgen een knop Wijzig en Verwijder. Alles wordt direct opgeslagen; je hoeft niets te bewaren."),
    ("blocks", "admin", "edit", "edit_mode:2", "Hoe werken blokken en rijen?", "Een pagina bestaat uit rijen met 1 tot 4 kolommen. In elke kolom zet je tekst, een afbeelding of een systeemobject. Sleep een onderdeel aan het greepje ⋮⋮ naar een andere plek; een blauwe lijn toont waar het landt. Met Verwijder haal je een onderdeel van de pagina."),
    ("layout", "admin", "edit", "edit_mode:2", "Hoe kies ik de opmaak van een pagina?", "Boven de blokken kies je een opmaak: onder elkaar, twee, drie of vier kolommen, hero met kaarten of breed en smal. De teksten blijven staan; alleen het raster verandert. Met Herstel zet je de standaardindeling van het thema terug."),
    ("hero", "admin", "edit", "edit_mode:2", "Hoe werken hero's?", "De hero is de banner bovenaan een pagina, in de kleuren van het thema. De banner van de pagina zelf zet je aan of uit. Daarnaast voeg je met Hero in de balk onderaan zoveel hero-blokken toe als je wilt, op elke plek, met een eigen hoogte: in pixels, een percentage van het scherm of volledig scherm. Elke hero heeft dezelfde opties als een pagina: een achtergrondafbeelding of video, donkerte, uitlijning en ruimte."),
    ("lists", "admin", "edit", "edit_mode:2", "Raster of rijen, centreren, breedte en pagineren", "Bij lijsten zoals spelletjes en producten kies je per pagina raster of rijen en of de items gecentreerd staan. Ook stel je in of de pagina in de kolom blijft of paginabreed is en hoeveel items per pagina je toont: 5, 10, 25, 100 of alles."),
    ("imgsize", "admin", "edit", "edit_mode:2", "Hoe groot maak ik een afbeelding?", "Kies bij een afbeelding Klein, Middel, Groot, Volledige breedte of Eigen formaat. Bij Eigen formaat typ je een breedte in pixels of procenten. Ook de uitlijning links, midden of rechts stel je daar in."),
    ("bg", "admin", "edit", "edit_mode:2", "Achtergrond van een rij of hero", "In bewerkmodus kies je bij een rij of de hero een afbeelding of video als achtergrond en bepaal je hoe donker die wordt, zodat tekst leesbaar blijft."),
    ("objects", "admin", "edit", "sysobjects:2", "Wat zijn systeemobjecten?", "Systeemobjecten zijn onderdelen van andere modules, zoals een donatieknop, een abonnement of een deel van de webshop, die je in bewerkmodus op een pagina zet. Admin → Systeemobjecten laat zien welke er zijn en je zet ze aan of uit."),
    ("theme", "admin", "design", "theme:1", "Hoe wissel ik van thema?", "Ga naar Admin → Website → Thema. Daar kies je een thema of themapakket met kleuren, lettertypen, vormen, logo's en e-mailopmaak. Wissel je van thema, dan veranderen ook de banners en voorbeelden mee."),
    ("themepack", "admin", "design", "theme:3", "Wat is een themapakket?", "Een themapakket is een zip met een compleet thema. Je kunt pakketten importeren, bewerken, downloaden of verwijderen. Easy2edit, RSTCC en Studio2 zijn ingebouwd en kun je niet verwijderen."),
    ("branding", "admin", "design", "branding:2", "Waar zet ik mijn logo?", "In Admin → Website → Logo's en beeld kies je het logo, het favicon, het app-icoon en de foto's van de homepage, ook een aparte versie voor donkere weergave."),
    ("media", "admin", "design", "media:1", "Hoe werkt de mediabibliotheek?", "In Admin → Media beheer je alle afbeeldingen en video's, lokaal of op S3. Uploaden kan ook in elk kiesvenster. Plaats je ergens een afbeelding, dan kies je altijd direct hoe hij staat: uitlijning en grootte."),
    ("email", "admin", "design", "communication:2", "Hoe ziet een e-mail eruit?", "De opmaak van e-mails stel je in bij het thema, tabblad E-mail, met een voorbeeld en een testmail. Afzenders, antwoordadressen en nummers staan bij Admin → Communicatie."),
    ("seo", "admin", "design", "seo:2", "Hoe vind ik mijn site in Google?", "In Admin → SEO stel je per pagina en taal de titel, omschrijving, afbeelding bij delen en noindex in. Ook robots.txt, de sitemap en llms.txt voor AI-agents worden daar beheerd."),
    ("shop", "admin", "adminplug", "plugin:webshop", "Hoe werkt de webshop?", "De webshop is een plugin. In Admin → Plugins → Webshop beheer je producten, groepen, verzendmethoden en kortingscodes. Op het tabblad Pagina's bewerk je de pagina's Producten, Product, Winkelwagen en Afrekenen en bij Instellingen stel je btw en online betalen in."),
    ("orders", "admin", "shop", "orders:1", "Waar zie ik bestellingen?", "In Admin → Orders staan alle bestellingen uit de webshop, abonnementen en donaties. Je ziet klantgegevens en status en kunt de status wijzigen of terugbetalen. Leden zien hun eigen bestellingen op Mijn bestellingen."),
    ("subs", "admin", "shop", "subscriptions:1", "Hoe maak ik een abonnement?", "In Admin → Abonnementen maak je abonnementen met een prijs, periode en proefperiode. Je koppelt acties aan een abonnement: wat een abonnee mag doen, tot wanneer en hoe vaak. Elke periode ontstaat een order. Abonnees en omzet zie je op het overzicht."),
    ("donate", "admin", "shop", "donations:1", "Hoe werken donaties?", "In Admin → Donaties maak je donatie-acties met een minimum, maximum en doelbedrag. Bezoekers kiezen het bedrag met een schuifbalk. Per actie stel je popups, bedankteksten en acties in die een donor erbij krijgt."),
    ("actions", "admin", "shop", "subscriptions:1", "Wat zijn acties?", "Acties zijn dingen die een gebruiker mag doen, zoals likes, chatten of een spel spelen. Je koppelt ze aan een abonnement of donatie met een 'geldig tot'. Het overzicht staat bij Admin → Acties, met voorstellen om te beginnen."),
    ("mysubs", "user", "money", "subscriptions:0", "Waar zie ik mijn abonnementen en donaties?", "Op Mijn abonnementen en Mijn donaties in je dashboard staan je lopende abonnementen, de einddatum en je gedane donaties. Daar verleng of zeg je een abonnement op."),
    ("profile", "user", "social", "profiles:0", "Hoe maak ik mijn profiel?", "Ga naar Mijn community → Wijzig profiel. Vul je gegevens in, voeg foto's toe en kies wie je profiel ziet: iedereen, leden, vrienden of geselecteerde leden. Je kunt ook instellen dat anderen je alleen zien als jij hen leuk vindt."),
    ("discover", "user", "social", "discover:0", "Hoe zoek en ontmoet ik mensen?", "Bij Zoeken & matchen zoek je andere leden met filters. Vind je iemand leuk, dan laat je dat weten; vinden jullie elkaar allebei leuk, dan is het een match. Wie je niet leuk vond, kun je niet meer tonen."),
    ("available", "user", "social", "profiles:0", "Wat betekent Beschikbaar voor?", "Hier kies je waarvoor je open staat, bijvoorbeeld games, een chat of een bepaald soort date. Anderen kunnen daarop zoeken."),
    ("messages", "user", "social", "messages:0", "Hoe stuur ik een bericht of chat ik?", "Berichten werken als een postvak. Chat is live, met foto's, video's en videochat. Beide gebruik je via Mijn community, als de beheerder ze heeft aangezet."),
    ("direct", "user", "social", "directconnect:0", "Wat is een directe verbinding?", "Met een directe verbinding praat je rechtstreeks met één ander, via een code, link of QR-code, ook zonder account. Je kunt chatten, foto's en video's delen en videobellen."),
    ("comm", "admin", "community", "profiles:3", "Hoe stel ik de community in?", "Admin → Community heeft twee tabbladen: Pagina's en Instellingen. Daar zet je de pagina's Community, Leden en Zoeken op orde en stel je profielen, zoeken, chat, directe verbinding en afstand in."),
    ("games", "admin", "adminplug", "plugin:games", "Hoe werken de spelletjes?", "Spelletjes zijn een plugin. Elk spel is een eigen pakket dat je uploadt, downloadt of verwijdert. Per spel stel je een leeftijdsgrens, publiek of alleen voor leden, uitleg met afbeeldingen en acties in. De pagina Spelletjes staat op /games of, voor leden, op /dashboard/games."),
    ("users", "admin", "people", "users:1", "Hoe beheer ik gebruikers?", "In Admin → Gebruikers zie je alle gebruikers. Je maakt ze aan, wijzigt ze en geeft ze rollen en groepen. Je kunt tussen lijst en tegels wisselen en pagineren."),
    ("roles", "admin", "people", "roles:1", "Wat zijn rollen en groepen?", "Een rol bundelt rechten. Een gebruikersgroep geeft de leden de rollen en toegang tot modules van de groep. Per module bepaal je of iemand het mag gebruiken (1), bewerken (2) of beheren (3)."),
    ("security", "admin", "security", "security_basic:1", "Welke beveiliging is er?", "Je stelt wachtwoordregels, inlogpogingen, sessies en aanmelden in. Daarnaast zijn er een landcontrole, een leeftijdscontrole, een gokken-popup, een cookiebanner en een woordfilter, elk aan of uit te zetten."),
    ("twofa", "user", "account", "member", "Hoe zet ik twee-staps verificatie aan?", "Ga naar je profiel en kies Twee-staps verificatie. Je krijgt een code per e-mail of sms, of gebruikt een authenticator-app. Een code werkt maar één keer."),
    ("modules", "super", "system", "staff", "Hoe zet ik modules aan of uit?", "Superadmins gaan naar Super admin → Modules. Een module die uit staat is nergens meer zichtbaar en haar API weigert verzoeken. Ook bepaal je daar wie een module mag gebruiken. De Easy2edit-help (dit uitleg-systeem) en de FAQ van je website zijn ook modules die je daar aan of uit zet."),
    ("plugins", "super", "system", "staff", "Wat zijn plugins?", "Plugins zijn losse, ondertekende programma's die je uploadt, zoals de webshop, de marktplaats en de spelletjes. Een plugin kan een eigen pagina, instellingen, menu-items en systeemobjecten meebrengen. Alleen superadmins beheren plugins."),
    ("themes", "super", "system", "staff", "Welke profielthema's kunnen kiezen?", "Superadmins zetten bij Super admin → Profielthema's aan welke thema's (Normaal, Sporters, Dating, Business, Webshop) de community-beheerders mogen kiezen. Alleen Normaal staat standaard aan."),
    ("maint", "admin", "system", "system:1", "Wat is de onderhoudsmodus?", "In onderhoudsmodus ziet iedereen een bericht in zijn eigen taal. Alleen een admin of superadmin kan nog inloggen op /login. Je zet hem aan bij het systeem."),
    ("apikeys", "admin", "system", "integrations:1", "Waarvoor dienen API keys?", "Bij Admin → API keys koppel je externe diensten zoals Claude, Stripe, S3 en Postmark. Claude wordt gebruikt om teksten in alle talen te maken."),
    ("backup", "super", "system", "staff", "Hoe maak ik een back-up of reset ik het systeem?", "Bij Super admin exporteer en importeer je instellingen, thema's en plugins in één bestand. Met Systeem resetten wis je alle gegevens en zet je alles terug naar de standaard; dat vraagt een bevestiging met een wachtwoord."),
    ("easy", "user", "start", "all", "Waarom staat Easy2edit onderaan?", "Onderaan elke pagina staat een kleine vermelding van Easy2edit. Een superadmin zet die aan of uit bij Admin → Overzicht → Over Easy2edit."),
    ("chat", "user", "social", "chat:0", "Hoe chat ik met iemand?", "Open Chat in je dashboard, kies een lid en typ een bericht. Je kunt foto's en video's sturen en, als het aan staat, videobellen. Chat is live; berichten in het postvak zijn voor als iemand er niet is."),
    ("swipe", "user", "social", "discover:0", "Hoe werkt swipen?", "Bij Zoeken & matchen zie je één profiel tegelijk. Veeg naar rechts als je iemand leuk vindt en naar links als niet. Met de terugknop maak je je laatste keuze ongedaan. Vind je elkaar leuk, dan is het een match en kun je contact opnemen."),
    ("hide", "user", "social", "discover:0", "Kan ik mensen verbergen die ik niet leuk vind?", "Ja. Wie je niet leuk vindt, zie je een tijd niet meer, of nooit meer als de beheerder dat aan heeft gezet. Zo blijft je lijst netjes."),
    ("visible", "user", "social", "profiles:0", "Wie kan mijn profiel zien?", "Bij Wijzig profiel kies je de zichtbaarheid: iedereen, leden, vrienden of geselecteerde leden. Zichtbaarheid staat standaard uit tot je hem aanzet. Je kunt ook instellen dat anderen je alleen zien als jij hen leuk vindt, en je kunt gebruikers blokkeren."),
    ("friends", "user", "social", "profiles:0", "Hoe werken vriendschaps- en foto-verzoeken?", "Je kunt een verzoek sturen om vrienden te worden of om iemands privéfoto's te zien. De ander accepteert of weigert. Je ziet je verzoeken bij Mijn community → Vrienden en verzoeken."),
    ("dating", "user", "social", "discover:0", "Hoe vind ik een date of een match?", "Zet bij je profiel aan waar je naar op zoek bent en voor welke leeftijd en afstand. Zoek daarna bij Zoeken & matchen met filters of swipe door de aanbevelingen. Matches en bezoekers zie je op je Mijn community-pagina."),
    ("chat2", "user", "social", "directconnect:0", "Kan ik chatten zonder account?", "Met een directe verbinding praat je met één ander via een link, code of QR-code. De ander heeft geen account nodig. Zodra jullie klaar zijn, sluit je de verbinding."),
    ("gameuser", "user", "social", "plugin+:games", "Hoe speel ik een spel?", "Open Spelletjes, kies een spel en klik op Spelen. Sommige spellen hebben een leeftijdsgrens: ben je te jong, dan krijg je een waarschuwing. Je scores worden bewaard en je speelt alleen of met anderen in een kamer."),
    ("shopuser", "user", "money", "plugin+:webshop", "Hoe bestel ik iets?", "Kies een product in de winkel, leg het in je winkelwagen en reken af. Of je online betaalt of achteraf een factuur krijgt hangt af van de winkel. Je bestellingen zie je terug bij Mijn bestellingen."),
    ("ordersuser", "user", "money", "orders:0", "Waar zie ik mijn bestellingen?", "Op Mijn bestellingen in je dashboard staan al je bestellingen met de status. Daar zie je ook of een bestelling al is betaald of verzonden."),
    ("subsuser", "user", "money", "subscriptions:0", "Hoe neem ik een abonnement?", "Kies op de pagina Abonnementen het abonnement dat bij je past en reken af. Daarna staat het op Mijn abonnementen, met de einddatum. Een abonnement geeft je extra mogelijkheden, zoals meer likes of chatten. Je kunt het opzeggen; het loopt dan nog door tot de einddatum."),
    ("donateuser", "user", "money", "donations:0", "Hoe doneer ik?", "Kies op de pagina Doneren een actie, schuif naar het bedrag en bevestig. Je kunt een bericht meegeven of anoniem blijven. Je donaties staan op Mijn donaties. Soms krijg je als dank extra mogelijkheden voor een tijd."),
    ("short", "user", "start", "member", "Hoe maak ik een snelkoppeling?", "Zoek een instelling of pagina en klik op het sterretje. De snelkoppeling komt op je dashboard. Klik nog eens op het sterretje om hem weg te halen."),
    ("tiles", "user", "start", "member", "Menu of tegels?", "Links boven in het dashboard wissel je tussen Menu en Tegels. Je keuze wordt onthouden, ook op een andere computer."),
    ("gamemanage", "admin", "adminplug", "plugin:games", "Hoe beheer ik de spelletjes?", "Ga naar Admin → Plugins → Spelletjes. Het tabblad Spellen toont alle spelletjes met aan/uit, instellingen, voorbeeld, download en verwijderen. Bij Pagina's pas je de pagina Spelletjes aan en bij Acties bepaal je wat een speler mag doen."),
    ("gameupload", "admin", "adminplug", "plugin:games", "Hoe upload ik een spel?", "Kies in Spelletjes → Spellen → Spel uploaden (zip) een zip met een map en een game.json, of sleep het bestand erheen. Een spel met dezelfde naam wordt bijgewerkt; instellingen en afbeelding blijven. Een zip downloaden en een spel verwijderen kan op dezelfde plek."),
    ("gameset", "admin", "adminplug", "plugin:games", "Wat stel ik per spel in?", "Per spel kies je de afbeelding, de titel en uitleg per taal (met Claude alle talen tegelijk), de leeftijdsgrens, of het spel publiek of alleen voor leden is, en hoeveel spelers het heeft. Een voorbeeld laat zien hoe het spel er voor spelers uitziet."),
    ("webpages", "admin", "adminplug", "plugin:webshop", "Hoe pas ik de winkelpagina's aan?", "In Admin → Plugins → Webshop → Pagina's bekijk en bewerk je Producten, Product, Winkelwagen en Afrekenen op het scherm. Sleep blokken, wijzig teksten en kies een opmaak. Btw en online betalen stel je in op het tabblad Instellingen."),
    ("themeupload", "admin", "design", "theme:3", "Hoe upload ik een thema?", "Ga naar Admin → Website → Thema's en kies Nieuw themapakket om een zip te uploaden. Daarna kies je Gebruik om het toe te passen, of Bewerken om kleuren, lettertypen en logo's te wijzigen. Een pakket kun je ook downloaden."),
    ("pluginupload", "super", "system", "staff", "Hoe upload en installeer ik een plugin?", "Ga naar Admin → Plugins en kies Plugin uploaden. Alleen een door de ontwikkelaar ondertekende plugin draait. Daarna zet je hem aan. Een nieuwe versie uploaden werkt de plugin bij; zijn gegevens blijven."),
    ("pluginset", "super", "system", "staff", "Hoe stel ik een plugin in?", "Open de plugin. Plaatsing bepaalt waar zijn pagina in het menu staat, of de pagina publiek is of achter de login (bijvoorbeeld /games of /dashboard/games) en of hij als systeemobject op een pagina mag. Bij Instellingen staan zijn eigen opties; ze worden vanzelf opgeslagen."),
    ("pluginpages", "super", "system", "staff", "Wat zijn de tabs Pagina's en Spellen van een plugin?", "Een plugin kan eigen websitepagina's meebrengen. Op het tabblad Pagina's bekijk en bewerk je ze op het scherm. Een plugin met eigen onderdelen, zoals spelletjes, heeft een tabblad om ze te uploaden en in te stellen."),
    ("pluginlang", "super", "system", "staff", "Hoe controleer ik de vertalingen van een plugin?", "Bij Overzicht en Details van de plugin zie je in welke talen hij vertaald is en wat ontbreekt. Een plugin vertaal je met de tool plugin_translate."),
    ("heroblock", "admin", "edit", "edit_mode:2", "Hoe voeg ik een hero-blok toe?", "Klik in de bewerkmodus onderaan de pagina op Hero. Je krijgt een banner met een tekstblok. Kies bij Hoogte Pixels, Procent van het scherm of Volledig scherm en geef er een achtergrond van afbeelding of video aan. Je kunt meer dan één hero toevoegen en ze met de pijltjes verplaatsen."),
    ("padding", "admin", "edit", "edit_mode:2", "Hoe stel ik de ruimte (padding) in?", "Boven de blokken kies je de ruimte van de hele pagina: Geen, Klein, Normaal, Groot of Extra groot. Per rij kun je dat overschrijven met Ruimte boven en onder."),
    ("loader", "admin", "design", "theme:2", "Hoe stel ik een paginaloader in?", "Ga naar Admin → Website → Thema → Laden. Zet de paginaloader aan, kies uit negen soorten die de kleuren van het thema volgen, en stel in wanneer hij verschijnt, de achtergrond, de doorzichtigheid, de grootte en hoe lang hij minimaal zichtbaar is. Met Test de loader zie je het resultaat meteen. Daar zet je ook lazy load aan, zodat afbeeldingen pas laden als ze in beeld komen."),
    ("transition", "admin", "design", "theme:2", "Wat zijn pagina-overgangen en scrolleffecten?", "Ook onder Thema → Laden. Een pagina-overgang is het effect als je naar een andere pagina gaat: vervagen, schuiven, inzoomen of scherp worden. Scrolleffecten laten onderdelen verschijnen als ze in beeld komen en kennen parallax, een voortgangsbalk en een knop terug naar boven. Voor mensen die minder beweging willen staat dit automatisch uit."),
    ("faqown", "admin", "site", "faq:1", "Hoe maak ik mijn eigen FAQ?", "Ga naar Admin → FAQ en klik op Nieuwe vraag. Vul de vraag en het antwoord per taal in, of laat Claude ze in alle talen vertalen. Je zet vragen aan of uit en bepaalt de volgorde. De vragen staan op /faq; zet die pagina zelf in het menu bij Pagina's."),
    ("helplayers", "super", "system", "staff", "Hoe werkt de Help van Easy2edit?", "De Help heeft drie lagen: Gebruiker, Beheer en Super admin, elk met uitleg voor wie daar rechten voor heeft. Je vindt hem als Help in het dashboard, in het Admin-menu en in het Super admin-menu. Alleen onderdelen die aan staan en waarvoor je rechten hebt komen in beeld."),
    ("undo", "admin", "edit", "edit_mode:2", "Kan ik een wijziging ongedaan maken?", "Ja. In bewerkmodus staat rechtsboven een pijl terug. Elke klik zet de laatste wijziging terug, tot 10 stappen: teksten, afbeeldingen, blokken en hun instellingen. De sneltoets is Ctrl of Cmd + Z. Het getal bij de pijl laat zien hoeveel stappen je nog kunt terugzetten."),
    ("helpmode", "admin", "edit", "edit_mode:2", "Hoe werkt de help in de bewerkmodus?", "Klik rechtsboven op het vraagteken. De pagina wordt donker en als je een icoon of onderdeel aanwijst, verschijnt uitleg over wat het doet. Druk op Esc of op het vraagteken om te sluiten. Beheerders wijzigen de teksten bij Admin → Help-teksten, per taal."),
    ("columns", "admin", "edit", "edit_mode:2", "Hoe maak ik een kolomindeling?", "Open het tandwiel linksboven in een blok of hero en kies bij Kolomindeling een tegel, bijvoorbeeld 50/50, 66/33 of drie gelijke kolommen. Wat al in het blok stond blijft staan en je sleept onderdelen naar een andere kolom. Op een smal scherm komen de kolommen onder elkaar."),
    ("fullwidth", "admin", "edit", "edit_mode:2", "Kan een blok de volle breedte van de browser gebruiken?", "Ja. Kies in het tandwiel van een blok bij Breedte is een deel van: De hele browser. Daarna bepaal je met Breedte het percentage van het scherm. Zo loopt bijvoorbeeld een hero van rand tot rand."),
    ("blockfx", "admin", "edit", "edit_mode:2", "Kan elk blok een eigen scrolleffect hebben?", "Ja. In het tandwiel van een blok of hero staat Scrolleffect: zoals het thema, geen effect, of een eigen effect zoals vervagen, omhoog of omlaag schuiven, van links of rechts, inzoomen en scherp worden."),
    ("heroalign", "admin", "edit", "edit_mode:2", "Hoe lijn ik de inhoud van een hero uit in de hoogte?", "Kies bij de hero eerst een hoogte (pixels, procent van het scherm of volledig scherm). Daarna kies je bij Uitlijnen in de hoogte: boven, gecentreerd of onder. Bij een automatische hoogte is er niets uit te lijnen."),
    ("blockstyle", "admin", "edit", "edit_mode:2", "Hoe geef ik een blok een achtergrondkleur of lettertype?", "In het tandwiel van een blok of hero staat Opmaak van dit blok. Kies een achtergrondkleur uit het palet van het thema of een eigen kleur, met doorzichtigheid, een tekstkleur, een lettertype en ronde hoeken in pixels. Terug naar thema zet alles weer op de standaard."),
    ("textsettings", "admin", "edit", "edit_mode:2", "Hoe pas ik een tekst of afbeelding apart aan?", "Elke tekst en elke afbeelding heeft een tandwiel. Bij tekst kies je een tekststijl van het thema (Kop 1 tot 4 of Alinea), een eigen grootte, kleur of lettertype. Bij een afbeelding kies je de uitlijning links, midden of rechts, de grootte in pixels of procenten, de doorzichtigheid en ronde hoeken."),
    ("movefixed", "admin", "edit", "edit_mode:2", "Kan ik het logo of de titel in een blok slepen?", "Ja, op de homepage. Het logo, de titel en de intro hebben een sleepicoon op de hoek van hun stippellijn. Sleep ze naar een kolom van een blok of hero. Verwijder je ze daar weer, dan komen ze terug op hun oude plek."),
    ("textstyles", "admin", "design", "theme:2", "Hoe stel ik koppen en alinea's in het thema in?", "Ga naar Admin → Website → Thema → Vormgeving → Tekststijlen. Per stijl (Kop 1 tot 4 en Alinea) stel je grootte, dikte, kleur, lettertype, regelafstand en letterafstand in. Elk thema heeft eigen waarden en de teksten in blokken en pagina's volgen ze."),
    ("loaderpct", "admin", "design", "theme:2", "Kan ik een percentage onder de loader tonen?", "Ja. Zet bij Thema → Laden → Paginaloader de schakelaar Percentage tonen onder de animatie aan. Er loopt dan een getal van 0 tot 100% mee. Het is een schatting, geen echte meting."),
    ("transswitch", "admin", "design", "theme:2", "Kan ik de pagina-overgang uitzetten?", "Ja. Bij Thema → Laden → Pagina-overgang staat de schakelaar Pagina-overgang gebruiken. Uit betekent geen effect. Aan toont de keuzes vervagen, schuiven, inzoomen en scherp worden, met een duur."),
    ("themeswitch", "super", "system", "staff", "Hoe kies ik welke profielthema's beschikbaar zijn?", "Ga naar Super admin → Profielthema's. Daar zet je per thema (Normaal, Sporters, Dating, Business, Webshop) aan of het gekozen mag worden. Alleen Normaal staat standaard aan en een thema dat in gebruik is blijft aan."),
]
